<include file="Public:header"/><div class="mainbox">	<div id="nav" class="mainnav_title">		<ul>			<a href="{pigcms{:U('Recruit/course_list')}">视频列表</a>|			<a href="{pigcms{:U('Recruit/course_commend')}">评论列表</a>|			<a href="{pigcms{:U('Recruit/course_category')}" class="on">分类列表</a>		</ul>	</div>	<div>		<input type="button" value="添加分类" class="button" onclick="window.top.artiframe('{pigcms{:U('course_category_edit')}','添加分类',800,480,true,false,false,addbtn,'add',true);"/>	</div>	<form name="myform" id="myform" action="" method="post" frame="true" refresh="true">		<div class="table-list">			<table width="100%" cellspacing="0">				<thead>					<tr>						<th>编号</th>						<th>名称</th>						<th>是否隐藏</th>						<th>操作</th>					</tr>				</thead>				<tbody>					<if condition="$list">						<volist name="list" id="vo">							<tr>								<td>{pigcms{$vo.id}</td>								<td>{pigcms{$vo.name}</td>								<td>                                <if condition="$vo['is_hide'] eq 1">                                	<span style="color: red;">是</span>                                <else/>                                	<span style="color: green;">否</span>                                </if>                            	</td>								<td>									<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('course_category_edit',array('id'=>$vo['id']))}','编辑',600,500,true,false,false,editbtn,'edit',true);">编辑</a>|									<a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('course_category_del')}">删除</a>							  	</td>							</tr>						</volist>						<tr><td class="textcenter pagebar" colspan="15">{pigcms{$list.pagebar}</td></tr>					<else/>						<tr><td class="textcenter red" colspan="16">列表为空！</td></tr>					</if>				</tbody>			</table>		</div>	</form></div><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script><include file="Public:footer"/>